css:
.mp-page { height: 100dvh; overflow: hidden; display: flex; flex-direction: column; gap: 14px; padding: clamp(20px, 3.2vh, 34px) clamp(24px, 3.4vw, 52px); background: var(--mp-panel); color: var(--mp-ink); }
.mp-head { display: grid; gap: 8px; }
.mp-title { margin: 0; font-size: clamp(26px, 2.4vw, 34px); line-height: 1.2; letter-spacing: -0.01em; }
.mp-sub { margin: 0; font-size: 15px; line-height: 1.5; color: var(--mp-muted); }
.mp-body { flex: 1; min-height: 0; display: grid; align-content: start; gap: 14px; }
.mp-card { padding: 16px 18px; border: 1px solid var(--mp-border); border-radius: 18px; background: var(--mp-raised); }
.mp-section-title { margin: 0 0 8px; font-size: 18px; line-height: 1.35; }
.mp-text { margin: 0; font-size: 15px; line-height: 1.7; }
.mp-check { display: grid; gap: 8px; margin-top: 10px; }
.mp-option { padding: 9px 12px; border: 1px solid var(--mp-border); border-radius: 12px; background: var(--mp-panel); color: var(--mp-ink); text-align: left; font: inherit; font-size: 14px; cursor: pointer; }
.mp-option[data-mp-state="correct"] { border-color: var(--mp-ink); background: var(--mp-raised); }
.mp-option[data-mp-state="wrong"] { color: var(--mp-muted); }
.mp-feedback { margin: 8px 0 0; font-size: 13px; color: var(--mp-muted); }
.mp-foot { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding-top: 12px; border-top: 1px solid var(--mp-border); }
.mp-progress { margin: 0; font-size: 13px; color: var(--mp-muted); }
.mp-actions { display: flex; gap: 10px; }
.mp-btn { min-height: 36px; padding: 7px 14px; border: 1px solid var(--mp-border); border-radius: 12px; background: var(--mp-panel); color: var(--mp-ink); font: inherit; font-size: 14px; cursor: pointer; }
.mp-btn-primary { border-color: var(--mp-invert); background: var(--mp-invert); color: var(--mp-invert-ink); }
@media (prefers-reduced-motion: reduce) { .mp-page * { animation: none; transition: none; } }
@media (max-width: 767px) { .mp-foot { flex-wrap: wrap; } }

js:
(function () {
  var root = document.querySelector('.mp-page');
  var ids = ['b1', 'b2', 'b3'];
  var blocks = ids.map(function (id) { return root.querySelector('[data-mp-block="' + id + '"]'); });
  var progress = root.querySelector('[data-mp-progress]');
  var next = root.querySelector("[data-mp-action='next']");
  var complete = root.querySelector("[data-mp-action='complete']");
  var feedback = root.querySelector('[data-mp-feedback]');
  var current = 1;
  function render() {
    blocks.forEach(function (block, index) { block.hidden = index > current - 1; });
    progress.textContent = '第 ' + current + ' / 3 步';
    next.disabled = current >= 3;
    MockFinal.emit('progress', { step: current, total: 3 });
  }
  next.addEventListener('click', function () {
    if (current < 3) { current += 1; render(); }
  });
  root.querySelectorAll('[data-mp-choice]').forEach(function (button) {
    button.addEventListener('click', function () {
      var correct = button.getAttribute('data-mp-choice') === 'a';
      button.dataset.mpState = correct ? 'correct' : 'wrong';
      feedback.hidden = !correct;
      if (correct) MockFinal.emit('interaction', { id: 'bisect-check', answer_index: 0 });
    });
  });
  complete.addEventListener('click', function () {
    MockFinal.emit('complete', { interactions_done: 1 });
  });
  render();
  MockFinal.ready({ title: '循环不变式：守住答案再砍半' });
})();
